effect.shader:
void main() {
    if (len <= 0.0) { fragColor = texture(inputImg, acScreenNorm); return; }
    int n = clamp(int(samples), 4, 48);
    float rad = radians(angle);
    vec2 dir = vec2(cos(rad), sin(rad));
    dir.x /= acAspect;

    vec4 soma = vec4(0.0);
    float pesoTot = 0.0;
    for (int i = 0; i <= 48; i++) {
        if (i > n) break;
        float t = float(i) / float(n);
        float w = pow(1.0 - t, falloff);
        soma += texture(inputImg, acScreenNorm - dir * len * t) * w;
        pesoTot += w;
    }
    fragColor = soma / max(pesoTot, 1e-4);
}
